import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
def load(f): return pd.read_csv(f).iloc[::5].reset_index(drop=True)
D=[load(f) for f in sorted(glob.glob('train/*.csv'))];VD=[load(f) for f in glob.glob('val/*.csv')]
def simQ(p,d):
    a,T1,b,T2,c,Tw,kd=p
    t=d.time_s.values;dt=t[1]-t[0];V=d.voltage_pu.values;th=d.bus_angle_rad.values;vs=d.voltage_setpoint_pu.values
    Q0=d.reactive_power_pu[0];V0=V[0];x1=x2=0;tf=th[0];Q=[]
    for i in range(len(t)):
        om=(th[i]-tf)/Tw;tf+=dt*om
        x1+=dt*(a*(V[i]-V0)-x1)/T1
        x2+=dt*(b*(vs[i]-V0)-x2)/T2
        Q.append(Q0+x1+x2+c*(V[i]-V0)+kd*om)
    return np.array(Q)
def res(p,DS): return np.concatenate([simQ(p,d)-d.reactive_power_pu.values for d in DS])
best=None
for T1 in [0.05,0.3]:
 for T2 in [0.3,2]:
  r=least_squares(res,[1,T1,10,T2,0,0.1,0],args=(D,),bounds=([-50,.01,-100,.01,-50,.02,-1],[50,10,100,20,50,2,1]))
  print(r.cost,r.x.round(3).tolist())
  if best is None or r.cost<best.cost:best=r
print(np.sqrt(np.mean(res(best.x,VD)**2)))
